//! Hand-written bindings for the parts of Hypervisor.framework (x86-64, VMX)
//! we use. Constants come from the macOS 26 SDK headers (hv_arch_x86.h,
//! hv_arch_vmx.h, hv_types.h), generated by compiling a C file that prints them.
#![allow(non_camel_case_types, dead_code, clippy::upper_case_acronyms)]

use std::ffi::c_void;

pub type hv_return_t = i32;
pub type hv_vcpuid_t = u32;

pub const HV_SUCCESS: hv_return_t = 0;
pub const HV_ERROR: hv_return_t = 0xfae9_4001_u32 as i32;

pub const HV_MEMORY_READ: u64 = 1 << 0;
pub const HV_MEMORY_WRITE: u64 = 1 << 1;
pub const HV_MEMORY_EXEC: u64 = 1 << 2;

